import { useEffect, useState } from "react";
import type {
	InteractionAction,
	InteractionView,
} from "@/components/agents/interaction-card";
import { mountMcpApp, useMcpApp } from "../_shared/host";
import { McpResultView } from "./result-view";
import "./app.css";

/**
 * The single MCP App bundle. It renders whatever `{title, blocks, actions}`
 * view the host streams and routes each action through the standard MCP Apps
 * bridge (`tools/call` or `ui/open-link`) — every interactive interaction is
 * just a different view through this one bundle.
 * All MCP-transport plumbing lives in `../_shared/host`.
 */

/** Sample view shown when opened standalone (dev/test, not embedded). */
const DEV_MOCK: InteractionView = {
	version: 1,
	title: "Update agent support-triage",
	tone: "warning",
	blocks: [
		{
			type: "diff",
			fields: [
				{
					label: "description",
					before: "Answers support questions on request",
					after: "Triages #support and drafts replies every morning",
				},
			],
		},
	],
	actions: [
		{
			id: "review",
			label: "Review in Lobu",
			variant: "primary",
			icon: "external",
			terminal: false,
			href: "https://lobu.ai/example/runs/42",
		},
	],
};

function InteractionApp() {
	const { data, callTool, openLink, lastResult, allowSpaHostedViews } =
		useMcpApp<unknown>();
	const [pendingId, setPendingId] = useState<string | null>(null);

	// Host brokered the `tools/call`; the returned structured result replaces
	// the card on success, while errors simply re-enable the original action.
	useEffect(() => {
		if (!lastResult) return;
		setPendingId(null);
	}, [lastResult]);

	if (!data) {
		return <div className="p-2 text-xs text-muted-foreground">Loading…</div>;
	}

	const onAction = (action: InteractionAction) => {
		if (action.href) {
			void openLink(action.href);
			return;
		}
		if (!action.tool) return;
		if (action.terminal !== false) setPendingId(action.id);
		void callTool(action.tool, action.args ?? {});
	};

	return (
		<McpResultView
			value={data}
			onAction={onAction}
			openLink={(href) => void openLink(href)}
			pendingId={pendingId}
			allowSpaHostedViews={allowSpaHostedViews}
		/>
	);
}

mountMcpApp({ devMock: DEV_MOCK, App: InteractionApp });
import { App, PostMessageTransport } from "@modelcontextprotocol/ext-apps";
import {
	createContext,
	type FC,
	type ReactNode,
	useContext,
	useEffect,
	useState,
} from "react";
import { createRoot } from "react-dom/client";
import { isExternalHttpUrl } from "./view";

/** Shared iframe-side runtime for every Lobu MCP App bundle. */

type ToolArgs = Record<string, unknown>;

interface McpAppApi<T> {
	/** Server-authored LobuViewV1 from the originating tool result. */
	data: T | null;
	/** Ask the host to broker a standard MCP `tools/call`. */
	callTool: (name: string, args: ToolArgs) => Promise<void>;
	/** Ask the host to open an external URL via `ui/open-link`. */
	openLink: (href: string) => Promise<void>;
	/** Latest app-initiated tool result; `seq` bumps so effects react to retries. */
	lastResult: { isError: boolean; seq: number } | null;
	/** True only inside Lobu's same-origin SPA parent, never in an external host. */
	allowSpaHostedViews: boolean;
}

const McpAppContext = createContext<McpAppApi<unknown>>({
	data: null,
	callTool: async () => {},
	openLink: async () => {},
	lastResult: null,
	allowSpaHostedViews: false,
});

/** Typed accessor for the host bridge inside a bundle's card component. */
export function useMcpApp<T>(): McpAppApi<T> {
	return useContext(McpAppContext) as McpAppApi<T>;
}

const isEmbedded = window.parent !== window;

function hasSameOriginParent(): boolean {
	if (!isEmbedded) return true;
	try {
		return window.parent.location.origin === window.location.origin;
	} catch {
		return false;
	}
}

function isStructuredObject(value: unknown): value is Record<string, unknown> {
	return Boolean(value) && typeof value === "object" && !Array.isArray(value);
}

function approvalCapabilityFromMeta(meta: unknown): string | null {
	if (!isStructuredObject(meta)) return null;
	const token = meta["lobu/approval-capability"];
	return typeof token === "string" && token.length <= 4_096 ? token : null;
}

function applyTheme(theme: "light" | "dark" | undefined): void {
	const dark = theme
		? theme === "dark"
		: window.matchMedia("(prefers-color-scheme: dark)").matches;
	document.documentElement.classList.toggle("dark", dark);
}

function Provider<T>({
	devMock,
	children,
}: {
	devMock: T;
	children: ReactNode;
}) {
	const [data, setData] = useState<T | null>(isEmbedded ? null : devMock);
	const [lastResult, setLastResult] = useState<{
		isError: boolean;
		seq: number;
	} | null>(null);
	const [app, setApp] = useState<App | null>(null);
	const [approvalCapability, setApprovalCapability] = useState<string | null>(
		null,
	);
	const allowSpaHostedViews = hasSameOriginParent();

	useEffect(() => {
		if (!isEmbedded) {
			applyTheme(undefined);
			return;
		}

		const nextApp = new App(
			{ name: "Lobu Interaction", version: "1.0.0" },
			{},
			{ autoResize: true, strict: true },
		);
		const transport = new PostMessageTransport(window.parent, window.parent);
		const onToolResult = (params: {
			structuredContent?: unknown;
			_meta?: unknown;
		}) => {
			if (isStructuredObject(params.structuredContent)) {
				setData(params.structuredContent as T);
			}
			setApprovalCapability(approvalCapabilityFromMeta(params._meta));
		};
		const onHostContext = (params: { theme?: "light" | "dark" }) =>
			applyTheme(params.theme);
		nextApp.addEventListener("toolresult", onToolResult);
		nextApp.addEventListener("hostcontextchanged", onHostContext);
		setApp(nextApp);
		void nextApp
			.connect(transport)
			.then(() => applyTheme(nextApp.getHostContext()?.theme))
			.catch((error) => {
				console.error("[mcp-app] failed to initialize", error);
			});

		return () => {
			nextApp.removeEventListener("toolresult", onToolResult);
			nextApp.removeEventListener("hostcontextchanged", onHostContext);
			void transport.close();
		};
	}, []);

	const callTool = async (name: string, args: ToolArgs) => {
		if (!app) {
			if (!isEmbedded) {
				console.log("[mcp-app] tools/call", name, args);
				setLastResult((last) => ({
					isError: false,
					seq: (last?.seq ?? 0) + 1,
				}));
			}
			return;
		}
		try {
			const result = await app.callServerTool({
				name,
				arguments: args,
				...(name === "resolve_lobu_approval" && approvalCapability
					? { _meta: { "lobu/approval-capability": approvalCapability } }
					: {}),
			});
			if (isStructuredObject(result.structuredContent)) {
				setData(result.structuredContent as T);
			}
			if (name === "resolve_lobu_approval" && result.isError !== true) {
				setApprovalCapability(null);
			}
			setLastResult((last) => ({
				isError: result.isError === true,
				seq: (last?.seq ?? 0) + 1,
			}));
		} catch {
			setLastResult((last) => ({
				isError: true,
				seq: (last?.seq ?? 0) + 1,
			}));
		}
	};

	const openLink = async (href: string) => {
		if (!isExternalHttpUrl(href)) {
			console.warn("[mcp-app] refused non-HTTP external link");
			return;
		}
		if (!app) {
			if (!isEmbedded) console.log("[mcp-app] ui/open-link", href);
			return;
		}
		try {
			const result = await app.openLink({ url: href });
			if (result.isError) console.warn("[mcp-app] host rejected external link");
		} catch {
			console.warn("[mcp-app] host rejected external link");
		}
	};

	return (
		<McpAppContext.Provider
			value={{ data, callTool, openLink, lastResult, allowSpaHostedViews }}
		>
			{children}
		</McpAppContext.Provider>
	);
}

/** Mount a bundle's card as a standalone MCP App with the standard bridge. */
export function mountMcpApp<T>(opts: { devMock: T; App: FC }): void {
	const { devMock, App: View } = opts;
	createRoot(document.getElementById("root") as HTMLElement).render(
		<Provider devMock={devMock}>
			<View />
		</Provider>,
	);
}
