/**
 * Post-build tripwire for MCP Apps. The Apps resource is a single HTML file
 * rendered on an isolated host, so it must not depend on Lobu's SPA assets.
 */
import { readFile } from "node:fs/promises";

// Keep the resources/read payload comfortably small enough for embedding hosts.
// The previous 2 MB bundle was present and valid but ChatGPT rejected it before
// the iframe started, so this is an intentionally conservative repository gate.
const MAX_RESOURCE_RESPONSE_BYTES = 1_000_000;
const bundleUrl = new URL(
	"../dist-mcp-apps/interaction/index.html",
	import.meta.url,
);
const source = await readFile(bundleUrl, "utf8");
const sourceBytes = Buffer.byteLength(source, "utf8");
const resourceResponseBytes = Buffer.byteLength(
	JSON.stringify({
		jsonrpc: "2.0",
		id: 1,
		result: {
			contents: [
				{
					uri: "ui://lobu/interaction/v1",
					mimeType: "text/html;profile=mcp-app",
					text: source,
					_meta: {
						ui: {
							csp: {
								connectDomains: [],
								resourceDomains: [],
								frameDomains: [],
							},
							prefersBorder: true,
						},
					},
				},
			],
		},
	}),
	"utf8",
);
const css = [...source.matchAll(/<style\b[^>]*>([\s\S]*?)<\/style>/gi)]
	.map((match) => match[1])
	.join("\n");
const runtimeCssUrls = [
	...css.matchAll(/url\(\s*(["']?)(?!data:|#)([^)"']+)\1\s*\)/gi),
].map((match) => match[2].trim());
const requiredStoredTemplateSelectors = [
	".space-y-3",
	".gap-4",
	".pr-4",
	".pt-6",
	".grid-cols-\\[repeat\\(auto-fill\\,minmax\\(200px\\,1fr\\)\\)\\]",
];

const errors = [];
if (source.includes("/fonts/")) {
	errors.push("font URLs remain in the single-file MCP App bundle");
}
if (!source.includes('http-equiv="Content-Security-Policy"')) {
	errors.push("defense-in-depth Content Security Policy is missing");
}
if (runtimeCssUrls.length > 0) {
	errors.push(`runtime CSS URLs remain: ${runtimeCssUrls.join(", ")}`);
}
if (resourceResponseBytes > MAX_RESOURCE_RESPONSE_BYTES) {
	errors.push(
		`resources/read JSON is ${resourceResponseBytes.toLocaleString()} bytes; budget is ${MAX_RESOURCE_RESPONSE_BYTES.toLocaleString()} bytes`,
	);
}
for (const selector of requiredStoredTemplateSelectors) {
	if (!css.includes(selector)) {
		errors.push(
			`stored json_template utility is missing from CSS: ${selector}`,
		);
	}
}

if (errors.length > 0) {
	console.error("MCP App bundle check FAILED:\n");
	for (const error of errors) console.error(`• ${error}`);
	process.exitCode = 1;
} else {
	console.log(
		`MCP App bundle check passed (${sourceBytes.toLocaleString()} HTML bytes; ${resourceResponseBytes.toLocaleString()} resources/read JSON bytes; self-contained, no runtime CSS assets).`,
	);
}
