const SESSION_MAX_AGE_MS = 60 * 60 * 1000; // 1 hour
const SESSION_CLEANUP_INTERVAL_MS = 10 * 60 * 1000; // 10 minutes
const MCP_APP_MIME_TYPE = 'text/html;profile=mcp-app';
const MCP_APP_EXTENSION_ID = 'io.modelcontextprotocol/ui';
