/** The single MCP App bundle (asset-only route backed by owletto's
 *  `build:mcp-apps`). Every interaction renders through it as a `{title, blocks,
 *  actions}` view. */
const INTERACTION_BUNDLE = "/mcp-apps/interaction/index.html";

/** Adapt a react-query mutation into a `Promise<isError>` the iframe bridge can
 *  resolve its `tools/call` on. */
function runMutation(
	run: (opts: { onSettled: (data: unknown, error: unknown) => void }) => void,
): Promise<boolean> {
	return new Promise((resolve) => {
		run({ onSettled: (_data, error) => resolve(Boolean(error)) });
	});
}

/**
 * Generic MCP App host: renders a `ui://` bundle in a sandboxed iframe
 * (`sandbox="allow-scripts"`, opaque origin, no cookies/DOM) and uses the stable
 * MCP Apps AppBridge lifecycle. The bundle receives tool input/result
 * notifications, reports size changes, and asks the host to broker tool calls
 * or external links. It never touches the API directly.
 */
const McpAppFrame: FC<{
	src: string;
	title: string;
	renderPayload: InteractionView;
	onToolCall: (name: string, args: Record<string, unknown>) => Promise<boolean>;
	onOpenLink: (url: string) => Promise<boolean>;
}> = ({ src, title, renderPayload, onToolCall, onOpenLink }) => {
	const iframeRef = useRef<HTMLIFrameElement>(null);
	const [height, setHeight] = useState(48);

	// Hold the render payload + broker in a ref so the message bridge subscribes
	// to `window` exactly once and never re-attaches on a parent re-render (which
	// would race an already-initialized iframe).
	const stateRef = useRef({ renderPayload, onToolCall, onOpenLink });
	stateRef.current = { renderPayload, onToolCall, onOpenLink };

	useEffect(() => {
		const iframe = iframeRef.current;
		if (!iframe?.contentWindow) return;

		const bridge = new AppBridge(
			null,
			{ name: "Lobu", version: "1.0.0" },
			{ openLinks: {}, serverTools: {} },
			{
				hostContext: {
					theme: document.documentElement.classList.contains("dark")
						? "dark"
						: "light",
					displayMode: "inline",
					platform: "web",
				},
			},
		);
		bridge.addEventListener("sizechange", ({ height: nextHeight }) => {
			if (typeof nextHeight === "number") {
				setHeight(Math.max(32, Math.ceil(nextHeight)));
			}
		});
		bridge.oncalltool = async ({ name, arguments: toolArgs }) => ({
			content: [],
			isError: await stateRef.current.onToolCall(name, toolArgs ?? {}),
		});
		bridge.onopenlink = async ({ url }) => ({
			isError: await stateRef.current.onOpenLink(url),
		});
		bridge.addEventListener("initialized", () => {
			void (async () => {
				await bridge.sendToolInput({ arguments: {} });
				await bridge.sendToolResult({
					content: [],
					structuredContent: {
						...stateRef.current.renderPayload,
						version: 1,
						source: SPA_HOSTED_VIEW_SOURCE,
					},
				});
			})();
		});

		const transport = new PostMessageTransport(
			iframe.contentWindow,
			iframe.contentWindow,
		);
		void bridge.connect(transport).catch((error) => {
			console.error("[mcp-app-host] failed to initialize", error);
		});
		const themeObserver = new MutationObserver(() => {
			bridge.setHostContext({
				theme: document.documentElement.classList.contains("dark")
					? "dark"
					: "light",
				displayMode: "inline",
				platform: "web",
			});
		});
		themeObserver.observe(document.documentElement, {
			attributes: true,
			attributeFilter: ["class"],
		});
		return () => {
			themeObserver.disconnect();
			void transport.close();
		};
	}, []);

	return (
		<iframe
			ref={iframeRef}
			title={title}
			src={src}
			sandbox="allow-scripts"
			style={{ width: "100%", height, border: "none", display: "block" }}
		/>
	);
};

/** The interaction card args the chat store folds from an SSE card payload. */
type InteractionArgs = {
	runId?: unknown;
	action?: string | null;
	proposal?: Record<string, unknown> | null;
	current?: Record<string, unknown> | null;
	requestId?: string | null;
	tool?: string;
	args?: unknown;
	durationOptions?: unknown;
	approveUrl?: string;
	orgSlug?: string | null;
	question?: string;
	options?: unknown;
	label?: string;
	url?: unknown;
	/** entity_field_change proposal: field_path -> proposed value. Present only
	 *  when the durable approval is an agent/behavior entity-field write blocked by
	 *  human ownership (server `interactionInput.fields`). */
	fields?: Record<string, unknown> | null;
	/** entity_field_change attribution: who proposed the change. */
	attribution?: "agent" | "behavior" | null;
	/** Discriminator from the worker: "agent" | "behavior" | "entity". */
	resourceKind?: "agent" | "behavior" | "entity" | null;
	reason?: unknown;
	status?: unknown;
	reviewedByName?: unknown;
};

/** Routing-only key shown in the card title — omit from the field list. */
const BEHAVIOR_ROUTING_KEYS = new Set(["action"]);

const DIFF_FIELDS = ["name", "description", "identity_md"] as const;

function diffValue(value: unknown): string {
	if (value === undefined || value === null || value === "") return "";
	if (typeof value === "string") return value;
	return safeStringify(value);
}

/** Format a behavior approval field for display, including explicit null clears. */
function behaviorFieldValue(value: unknown): string {
	if (value === null) return "(cleared)";
	if (value === undefined) return "";
	if (typeof value === "string") {
		if (value === "") return "";
		// Return the FULL value — a reviewer approves the complete original
		// (e.g. a reaction_script), so truncating would let unreviewed code in the
		// hidden tail be approved. The card container scrolls for long content.
		return value;
	}
	return safeStringify(value);
}

function capitalize(s: string): string {
	return s.length > 0 ? s[0].toUpperCase() + s.slice(1) : s;
}

/** entity_field_change approval → a per-field proposed-vs-current diff.
 *  An agent (or behavior reaction) tried to overwrite a field a human owns; the
 *  write was blocked and queued for the human to approve. */
function buildEntityFieldChangeView(
	a: InteractionArgs,
	proposedFields: Record<string, unknown>,
): InteractionView {
	const actorNoun = a.attribution === "behavior" ? "A Behavior" : "An agent";
	const paths = Object.keys(proposedFields);
	const fields = paths.map((path) => ({
		label: path,
		before: diffValue(a.current?.[path]),
		after: diffValue(proposedFields[path]),
	}));
	return {
		title: `${actorNoun} proposes a change`,
		tone: "warning",
		blocks:
			fields.length > 0
				? [{ type: "diff", fields }]
				: [{ type: "text", value: "No field changes.", muted: true }],
		actions: [
			{
				id: "approve",
				label: "Approve",
				variant: "primary",
				icon: "check",
				tool: "manage_operations",
				args: { action: "approve" },
				resolvedLabel: `Approved — ${paths.join(", ")} is being applied.`,
			},
			{
				id: "reject",
				label: "Reject",
				variant: "outline",
				icon: "x",
				confirm: true,
				confirmPrompt: "Reject this change?",
				tool: "manage_operations",
				args: { action: "reject" },
				resolvedLabel: `Rejected — ${paths.join(", ")} was not applied.`,
			},
		],
		],
	};
}

/** manage_behaviors create/update/delete approval → flat behavior field list. */
function buildBehaviorApprovalView(a: InteractionArgs): InteractionView {
	const verb = a.action ?? "change";
	const label =
		(a.proposal?.slug as string | undefined) ??
		(a.proposal?.name as string | undefined) ??
		(a.proposal?.behavior_id != null
			? String(a.proposal.behavior_id)
			: undefined) ??
		(a.current?.slug as string | undefined) ??
		(a.current?.name as string | undefined) ??
		"behavior";
	const blocks: InteractionBlock[] = [];
	if (a.action === "delete") {
		blocks.push({
			type: "text",
			value: "This will archive the Behavior.",
			muted: true,
		});
	}
	// Show every mutation field present on the proposal (including explicit null
	// clears and reaction_script / execution_config / device_worker_id). Only
	// `action` is omitted — it already drives the title.
	const proposal = a.proposal ?? {};
	const fields = Object.keys(proposal)
		.filter((f) => !BEHAVIOR_ROUTING_KEYS.has(f) && proposal[f] !== undefined)
		.map((f) => ({
			label: f,
			...(a.action === "update" && a.current?.[f] !== undefined
				? { before: behaviorFieldValue(a.current?.[f]) }
				: {}),
			after: behaviorFieldValue(proposal[f]),
		}));
	blocks.push(
		fields.length > 0
			? { type: "diff", fields }
			: { type: "text", value: "No field changes.", muted: true },
	);
	return {
		title: `${capitalize(verb)} Behavior ${label}`,
		tone: "warning",
		blocks,
		actions: [
			{
				id: "approve",
				label: "Approve",
				variant: "primary",
				icon: "check",
				tool: "manage_operations",
				args: { action: "approve" },
				resolvedLabel: `Approved — ${verb} ${label} is being applied.`,
			},
			{
				id: "reject",
				label: "Reject",
				variant: "outline",
				icon: "x",
				confirm: true,
				confirmPrompt: "Reject this change?",
				tool: "manage_operations",
				args: { action: "reject" },
				resolvedLabel: `Rejected — ${verb} ${label} was not applied.`,
			},
		],
	};
}

function isEntityMergeApproval(a: InteractionArgs): boolean {
	return (
		a.action === "merge" &&
		(a.resourceKind === "entity" ||
			a.proposal?.entity_id !== undefined ||
			a.proposal?.winner_entity_id !== undefined ||
			a.current?.winner !== undefined)
	);
}

/** Agent/entity create/update/delete approval → the proposed-vs-current diff. */
function buildApprovalView(a: InteractionArgs): InteractionView {
	// manage_behaviors proposals are tagged resourceKind:"behavior" so they are
	// not misrendered as agent create/update cards.
	if (a.resourceKind === "behavior") {
		return buildBehaviorApprovalView(a);
	}
	// entity_field_change proposals carry a `fields` map (arbitrary entity field
	// paths), distinct from the manage_agents gate's name/description/identity_md
	// `proposal`. Route them to the field-diff view.
